CREATE DATABASE IF NOT EXISTS invwedding CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE invwedding;
CREATE TABLE admins (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE admin_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, admin_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE template_categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, slug VARCHAR(120) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NULL, name VARCHAR(150) NOT NULL, slug VARCHAR(150) NOT NULL UNIQUE, description TEXT, price BIGINT UNSIGNED NOT NULL DEFAULT 0, folder VARCHAR(150) NOT NULL, thumbnail VARCHAR(255), status ENUM('draft','published','inactive') NOT NULL DEFAULT 'draft', featured TINYINT(1) NOT NULL DEFAULT 0, popular TINYINT(1) NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (category_id) REFERENCES template_categories(id) ON DELETE SET NULL, INDEX(status, sort_order)) ENGINE=InnoDB;
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, whatsapp VARCHAR(30) NOT NULL, email VARCHAR(190), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(whatsapp)) ENGINE=InnoDB;
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_number VARCHAR(30) NOT NULL UNIQUE, customer_id BIGINT UNSIGNED NOT NULL, status ENUM('pending_payment','waiting_confirmation','paid','processing','active','completed','cancelled') NOT NULL DEFAULT 'pending_payment', total BIGINT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (customer_id) REFERENCES customers(id)) ENGINE=InnoDB;
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, template_id BIGINT UNSIGNED NOT NULL, template_name VARCHAR(150) NOT NULL, price BIGINT UNSIGNED NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(template_id) REFERENCES templates(id)) ENGINE=InnoDB;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, method VARCHAR(50) DEFAULT 'manual_transfer', status ENUM('pending','verified','rejected') DEFAULT 'pending', note TEXT, paid_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE invitations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NULL, template_id BIGINT UNSIGNED NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, status ENUM('draft','active','expired','disabled') DEFAULT 'draft', wedding_date DATE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL, FOREIGN KEY(template_id) REFERENCES templates(id)) ENGINE=InnoDB;
CREATE TABLE couples (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invitation_id BIGINT UNSIGNED NOT NULL UNIQUE, bride_name VARCHAR(120), bride_full_name VARCHAR(180), groom_name VARCHAR(120), groom_full_name VARCHAR(180), FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invitation_id BIGINT UNSIGNED NOT NULL, type VARCHAR(80), title VARCHAR(150), event_date DATE, event_time VARCHAR(80), venue VARCHAR(180), address TEXT, maps_url VARCHAR(500), description TEXT, status TINYINT(1) DEFAULT 1, sort_order INT DEFAULT 0, FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE, INDEX(invitation_id,status)) ENGINE=InnoDB;
CREATE TABLE dress_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invitation_id BIGINT UNSIGNED NOT NULL UNIQUE, title VARCHAR(150), description TEXT, enabled TINYINT(1) DEFAULT 1, FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE live_streams (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invitation_id BIGINT UNSIGNED NOT NULL UNIQUE, title VARCHAR(150), url VARCHAR(500), enabled TINYINT(1) DEFAULT 1, FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE love_stories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invitation_id BIGINT UNSIGNED NOT NULL, year VARCHAR(20), title VARCHAR(150), description TEXT, photo VARCHAR(255), sort_order INT DEFAULT 0, FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE gallery (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invitation_id BIGINT UNSIGNED NOT NULL UNIQUE, FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE gallery_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, gallery_id BIGINT UNSIGNED NOT NULL, type ENUM('image','youtube') DEFAULT 'image', path VARCHAR(255), caption VARCHAR(255), sort_order INT DEFAULT 0, status TINYINT(1) DEFAULT 1, FOREIGN KEY(gallery_id) REFERENCES gallery(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE wedding_gifts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invitation_id BIGINT UNSIGNED NOT NULL UNIQUE, enabled TINYINT(1) DEFAULT 1, shipping_name VARCHAR(150), shipping_address TEXT, FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE wedding_gift_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, wedding_gift_id BIGINT UNSIGNED NOT NULL, bank VARCHAR(80), account_number VARCHAR(80), account_name VARCHAR(150), qris_image VARCHAR(255), FOREIGN KEY(wedding_gift_id) REFERENCES wedding_gifts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE guests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invitation_id BIGINT UNSIGNED NOT NULL, name VARCHAR(180) NOT NULL, whatsapp VARCHAR(30), token VARCHAR(80) UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE rsvps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invitation_id BIGINT UNSIGNED NOT NULL, guest_name VARCHAR(150) NOT NULL, whatsapp VARCHAR(30), attendance ENUM('hadir','tidak_hadir','ragu') NOT NULL, guest_count TINYINT UNSIGNED DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE wishes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invitation_id BIGINT UNSIGNED NOT NULL, name VARCHAR(150) NOT NULL, message TEXT NOT NULL, status ENUM('pending','approved','hidden') DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invitation_id) REFERENCES invitations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, setting_key VARCHAR(100) NOT NULL UNIQUE, setting_value TEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE seo_settings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, page_key VARCHAR(100) NOT NULL UNIQUE, title VARCHAR(255), description TEXT, og_image VARCHAR(255)) ENGINE=InnoDB;
